struct stat sb;
const char *path = "/path/to/link";
int ret;

// lstat64 retrieves status of the link file itself,
// regardless of what it points to.
ret = lstat64(path, &sb);

if (ret == 0) {
    // Check if the file descriptor refers to a link
    if ((sb.st_mode & S_IFMT) == S_IFLNK) {
        // Size of the link definition string
        off_t link_size = sb.st_size;
    }
} else {
    // Common error: EACCES (permission denied on directory)
    // or ENOENT (path does not exist)
}
